// crate: unicode-script-0.5.7/src/tables.rs:2129 bsearch_range_value_table
/** PORT: `r` is a flat [lo, hi, value-index] table (`width` 3) and `values` maps the third column to `T`. */
export function bsearch_range_value_table<T>(c: number, r: ArrayLike<number>, values: (i: number) => T): T | undefined {
  let lo = 0;
  let hi = r.length / 3;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    const rlo = r[mid * 3]!;
    const rhi = r[mid * 3 + 1]!;
    if (rlo <= c && c <= rhi) return values(r[mid * 3 + 2]!);
    else if (rhi < c) lo = mid + 1;
    else hi = mid;
  }
  return undefined;
}

